@import '~@proton/styles/scss/config';

.modal-two {
	position: fixed;
	inset: 0;
	z-index: $layer-modals;
	display: flex;
	padding: 3.5em;
	overflow: hidden;
	flex-flow: column nowrap;
	align-items: center;
	justify-content: center;
	animation: 0.1s ease-out forwards;
	animation-name: anime-modal-two-in;

	@include respond-to($breakpoint-small) {
		padding: 2em;
	}

	@include respond-to($breakpoint-tiny) {
		padding: 1em;
	}

	&--out {
		animation-name: anime-modal-two-out;
	}

	&--out &-dialog {
		animation-name: anime-modal-two-dialog-out;
	}

	&--fullscreen-on-mobile {
		@include respond-to($breakpoint-tiny) {
			padding: 0;
			align-items: stretch;
			background: none;
		}
	}

	&--fullscreen-on-mobile &-dialog {
		@include respond-to($breakpoint-tiny) {
			flex: 1 0 100%;
			border-radius: 0;
		}
	}

	&--fullscreen {
		padding: 0;
		align-items: stretch;
		background: none;
	}

	&--fullscreen &-dialog {
		flex: 1 0 100%;
		border-radius: 0;
		max-width: unset;
	}

	&--is-behind-backdrop {
		z-index: $layer-modals - 1;
	}

	@keyframes anime-modal-two-in {
		from {
			opacity: 0;
		}

		to {
			opacity: 1;
		}
	}

	@keyframes anime-modal-two-out {
		from {
			opacity: 1;
		}

		to {
			opacity: 0;
		}
	}

	&-dialog {
		--size: #{rem(480)}; // medium
		--margin: #{rem(32)};

		@include respond-to($breakpoint-small) {
			--margin: #{rem(24)};
		}

		position: relative;
		z-index: 1;
		display: flex;
		max-inline-size: var(--size);
		inline-size: 100%;
		overflow: hidden;
		padding: 0;
		margin: auto;
		transform-origin: center top;
		border-radius: var(--border-radius-lg);
		box-shadow: var(--shadow-lifted);
		background: var(--modal-background-color);
		color: var(--modal-text-color);
		animation: 0.25s easing(easeOutCubic) both;
		animation-name: anime-modal-two-dialog-in;

		&-container {
			flex-grow: 1;
			max-inline-size: 100%;
			display: flex;
			flex-flow: column nowrap;
			justify-content: flex-start;
			align-items: stretch;
		}

		&--small {
			--size: #{rem(392)};
			--margin: #{rem(24)};
		}

		&--large {
			--size: #{rem(600)};
		}

		&--full {
			--size: 100%;
			inline-size: var(--size);
		}

		@keyframes anime-modal-two-dialog-in {
			0% {
				transform: scale(0.9);
			}

			100% {
				transform: scale(1);
			}
		}

		@keyframes anime-modal-two-dialog-out {
			0% {
				transform: scale(1);
			}

			100% {
				transform: scale(0.9);
			}
		}
	}
}

import { useEffect, useLayoutEffect, useRef } from 'react';

import PropTypes from 'prop-types';

import { dialogRootClassName } from '@proton/shared/lib/busy';

import { classnames } from '../../helpers';
import { useHotkeys } from '../../hooks';
import { useFocusTrap } from '../focus';
import { useModalPosition } from '../modalTwo/modalPositions';
import Portal from '../portal/Portal';

const CLASSES = {
    MODAL: 'modal',
    MODAL_IN: 'modal--in',
    MODAL_OUT: 'modal--out',
    MODAL_INTERMEDIATE: 'modal--intermediate',
    MODAL_SMALL: 'modal--smaller',
    MODAL_TINY: 'modal--tiny',
};

const ANIMATIONS = {
    MODAL_IN: 'anime-modal-in',
    MODAL_OUT: 'anime-modal-out',
};

/**
 * @deprecated Please use ModalTwo instead
 * @type any
 */
const Dialog = ({
    onClose,
    onEnter,
    onExit,
    intermediate: isIntermediate = false,
    small: isSmall = false,
    tiny: isTiny = false,
    isClosing = false,
    modalTitleID,
    children,
    className: extraClassNames = '',
    disableCloseOnOnEscape,
    open, // To prevent it being passed in rest
    ...rest
}) => {
    const rootRef = useRef(null);
    const hasCalledExit = useRef(false);
    const hasCalledClose = useRef(false);
    const focusTrapProps = useFocusTrap({ rootRef });
    const last = useModalPosition(true);

    useLayoutEffect(() => {
        hasCalledClose.current = isClosing;
    }, [isClosing]);

    useEffect(() => {
        return () => {
            // Safety measure to make sure cleanup functions always get called, even if the component gets forcefully removed
            if (!hasCalledClose.current) {
                onClose?.();
            }
            if (!hasCalledExit.current) {
                onExit?.();
            }
        };
    }, []);

    useHotkeys(rootRef, [
        [
            'Escape',
            (e) => {
                if (!disableCloseOnOnEscape) {
                    e.stopPropagation();
                    onClose?.();
                }
            },
        ],
    ]);

    return (
        <Portal>
            <div className={classnames([dialogRootClassName, !last && 'is-behind-backdrop'])}>
                <dialog
                    aria-labelledby={modalTitleID}
                    aria-modal="true"
                    open
                    className={classnames([
                        CLASSES.MODAL,
                        isSmall && CLASSES.MODAL_SMALL,
                        isTiny && CLASSES.MODAL_TINY,
                        isIntermediate && CLASSES.MODAL_INTERMEDIATE,
                        (isSmall || isTiny || isIntermediate) && 'modal--shorter-labels',
                        isClosing && CLASSES.MODAL_OUT,
                        extraClassNames,
                        'outline-none',
                    ])}
                    onAnimationEnd={({ animationName }) => {
                        if (animationName === ANIMATIONS.MODAL_OUT && isClosing) {
                            hasCalledExit.current = true;
                            onExit?.();
                        }
                        if (animationName === ANIMATIONS.MODAL_IN && !isClosing) {
                            onEnter?.();
                        }
                    }}
                    {...rest}
                    ref={rootRef}
                    {...focusTrapProps}
                >
                    {children}
                </dialog>
            </div>
        </Portal>
    );
};

Dialog.propTypes = {
    onEnter: PropTypes.func,
    open: PropTypes.bool,
    onExit: PropTypes.func.isRequired,
    onClose: PropTypes.func.isRequired,
    children: PropTypes.node.isRequired,
    modalTitleID: PropTypes.string.isRequired,
    className: PropTypes.string,
    small: PropTypes.bool,
    isClosing: PropTypes.bool,
    disableCloseOnOnEscape: PropTypes.bool,
};

export default Dialog;

import { ChangeEvent, DetailedHTMLProps, InputHTMLAttributes, Ref, forwardRef } from 'react';

import { classnames } from '../../helpers';
import Icon, { IconName } from '../icon/Icon';
import { CircleLoader } from '../loader';

export interface ToggleProps extends DetailedHTMLProps<InputHTMLAttributes<HTMLInputElement>, HTMLInputElement> {
    loading?: boolean;
}

const Toggle = (
    {
        id = 'toggle',
        className = '',
        checked = false,
        loading = false,
        onChange,
        disabled,
        title,
        ...rest
    }: ToggleProps,
    ref: Ref<HTMLInputElement>
) => {
    const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
        if (!disabled && onChange) {
            onChange(event);
        }
    };
    const label = (name: IconName, condition: boolean) => {
        return (
            <span className="toggle-label-text" aria-hidden="true">
                <Icon name={name} alt="" size={16} className="toggle-label-img" />
                {condition && (
                    <span className="toggle-label-loader">
                        <CircleLoader />
                    </span>
                )}
            </span>
        );
    };
    return (
        <label
            htmlFor={id}
            className={classnames([
                'toggle-label',
                className,
                disabled && 'toggle-label--disabled',
                checked && 'toggle-label--checked',
                loading && 'toggle-label--loading',
            ])}
            title={title}
        >
            <input
                disabled={loading || disabled}
                id={id}
                onChange={handleChange}
                type="checkbox"
                className={classnames(['toggle-checkbox sr-only', className])}
                checked={checked}
                aria-busy={loading}
                ref={ref}
                {...rest}
            />
            {label('cross', loading && !checked)}
            {label('checkmark', loading && checked)}
        </label>
    );
};

export default forwardRef<HTMLInputElement, ToggleProps>(Toggle);

